\sum_{k=1}^{n} \log_2\left(1 + \frac{1}{k}\right) \log_k 2 \log_{k+1} 2 &= \sum_{k=1}^{n} \log_2\left(\frac{k+1}{k}\right) \log_k 2 \log_{k+1} 2 \\
&= \sum_{k=1}^{n} \left(\log_2(k+1) - \log_2(k)\right) \frac{1}{\log_2 k} \frac{1}{\log_2 (k+1)} \\
&= \sum_{k=1}^{n} \frac{1}{\log_2 k} - \frac{1}{\log_2 (k+1)} \\
&= \frac{1}{\log_2 1} - \frac{1}{\log_2 (n+1)} \\
&= 1 - \frac{1}{\log_2 (n+1)} \\
&= \boxed{1 - \frac{1}{\log_2 (n+1)}}
\end{align*}

